import { Lease, Source } from './source';
import { mapEvent } from './mapper';

export class EventService {
  constructor(
    private readonly source: Source,
    private readonly mapper: (value: string) => string = mapEvent,
  ) {}

  /**
   * Lazily opens a lease on first iteration and yields mapped records.
   * Guarantees:
   *  - the lease is closed exactly once ...
   */
  async *stream(): AsyncGenerator<string, void, undefined> {
    const lease = await this.source.open();
    // The "original" exception raised inside the pump (read, mapper or a
    // consumer-injected throw). When close fails while such an exception is
    // unwinding, the original then propagates.
    let originalException: { readonly error: unknown } | undefined;
    try {
      for (;;) {
        let value: string | null;
        try {
          value = await lease.read();
        } catch (error) {
          originalException = { error };
          throw error;
        }
        if (value === null) {
          break; // exhaustion read; establishes done, no further read
        }
        let mapped: string;
        try {
          mapped = this.mapper(value);
        } catch (error) {
          originalException = { error };
          throw error;
        }
        try {
          yield mapped;
        } catch (error) {
          // consumer-injected throw via .throw()
          originalException = { error };
          throw error;
        }
      }
    } finally {
      try {
        await lease.close();
      } catch (closeFailure) {
        // Preserve the original read, mapper or injected exception; otherwise
        // propagate the close failure (exhaustion or break/return path).
        if (originalException === undefined) {
          throw closeFailure;
        }
      }
    }
  }
}
