import { Source } from './source';
import { mapEvent } from './mapper';

export class EventService {
  constructor(
    private readonly source: Source,
    private readonly mapper: (value: string) => string = mapEvent,
  ) {}

  /**
   * Streams mapped values from a single source lease.
   *
   * - The lease is opened on the first iteration and never before (the body of
   *   an async generator does not start until the first next() call).
   * - Exactly one read is performed per next() call; the only extra read is
   *   the one that establishes exhaustion (resolving to null).
   * - The lease is closed exactly once, from a finally block, on normal
   *   exhaustion, on consumer break/return and whenever the read, the mapper
