// Builds a Source whose Lease serves a scripted read sequence. A script entry
// is a string value, `null` for end of stream, or an Error instance which
// makes that read() reject. Leases are instrumented so every open(), read()
// and close() is observable; both open() and close() can be made to fail.
function makeSource(script, { failOpen = undefined, failClose = undefined } = {}) {
  const state = { opens: 0, closes: 0, readLog: [], closeLog: [] };
  const source = {
    open: async () => {
      state.opens++;
      if (failOpen) throw failOpen;
      const queue = script.slice();
      return {
        read: async () => {
          const token = queue.length ? queue.shift() : null;
          state.readLog.push(token instanceof Error ? 'read!' : token === null ? 'END' : token);
          if (token instanceof Error) throw token;
          return token;
        },
        close: async () => {
          state.closeLog.push('close');
          state.closes++;
          if (failClose) throw failClose;
        },
      };
    },
  };
  return { source, state };
}

function mapRecording(mapperLog, failOn) {
  return (value) => {
    mapperLog.push(value);
    if (failOn === value) throw new Error('M');
    return value.toUpperCase();
